    18	func runServe(args []string) error {
    19		fs := flag.NewFlagSet("forgemark serve", flag.ContinueOnError)
    20		addr := fs.String("addr", "127.0.0.1:8377", "listen address; keep it loopback — this is a load-generation control panel")
    21		resultsDir := fs.String("results", "results", "directory for result JSON docs (shared with the CLI)")
    22		if err := fs.Parse(args); err != nil {
    23			if errors.Is(err, flag.ErrHelp) {
    24				return nil // -h/-help already printed usage; a help request isn't a failure
    25			}
    26			return err
    27		}
    28		// An empty host (":8377") is a wildcard bind — all interfaces — so it must
    29		// warn, not pass: server.IsLoopbackHost treats it as non-loopback.
    30		if host, _, err := net.SplitHostPort(*addr); err == nil && !server.IsLoopbackHost(host) {
    31			fmt.Fprintf(os.Stderr, "forgemark: WARNING: -addr %s is not loopback — anyone who can reach it can "+
    32				"drive benchmark runs. Credentials (pasted or CLI-sourced) and CLI discovery are refused on a "+
    33				"non-loopback bind, so only demo:// targets will run there. Only expose this on a network you trust.\n", *addr)
