// Thin fetch wrappers over the forgemark API. All errors surface as thrown
// Error objects carrying the server's message.

async function req(method, path, body) {
  const res = await fetch(path, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { /* non-JSON error body */ }
  if (!res.ok) {
    throw new Error((data && data.error) || `${res.status} ${res.statusText}`);
  }
  return data;
}

export const api = {
  startRun: (spec) => req('POST', '/api/runs', spec),
  listRuns: () => req('GET', '/api/runs'),
  getRun: (id) => req('GET', `/api/runs/${encodeURIComponent(id)}`),
  cancelRun: (id) => req('POST', `/api/runs/${encodeURIComponent(id)}/cancel`),
  history: () => req('GET', '/api/history'),
  historyDoc: (file) => req('GET', `/api/history/${encodeURIComponent(file)}`),
  localSuggest: () => req('GET', '/api/local/suggest'),
};
// EventSource wrapper for a run's event stream. The browser reconnects
// automatically and re-sends Last-Event-ID; the server replays anything
// missed, so handlers can treat the stream as gapless and in-order. The
// caller closes it on run_done — after that the stream only ever replays.

export function openRunStream(runId, handlers) {
  const es = new EventSource(`/api/runs/${encodeURIComponent(runId)}/events`);
  for (const [name, fn] of Object.entries(handlers)) {
    es.addEventListener(name, (ev) => fn(JSON.parse(ev.data)));
  }
  return es;
}

