    10	func TestWithDefaultsAbsentVsExplicitZero(t *testing.T) {
    11		got := WorkloadSpec{}.withDefaults()
    12		if *got.WarmupSec != 10 || *got.DurationSec != 60 || *got.FilesMin != 1 || *got.CloneDepth != 1 {
    13			t.Fatalf("absent fields should take CLI defaults, got %+v", got)
    14		}
    15		if len(got.Concurrency) != 4 {
    16			t.Fatalf("absent concurrency should default to the CLI sweep, got %v", got.Concurrency)
    17		}
    18	
    19		got = WorkloadSpec{Strategy: "clone", WarmupSec: f64(0), CloneDepth: i(0)}.withDefaults()
    20		if *got.WarmupSec != 0 {
    21			t.Fatalf("explicit warmup 0 (no warm-up) was rewritten to %v", *got.WarmupSec)
    22		}
    23		if *got.CloneDepth != 0 {
    24			t.Fatalf("explicit clone_depth 0 (full history) was rewritten to %v", *got.CloneDepth)
    25		}
    26	
    27		// Explicit empty concurrency stays empty so Validate rejects it — it must
    28		// NOT silently become the default [1,8,32,128] sweep.
    29		got = WorkloadSpec{Concurrency: []int{}}.withDefaults()
    30		if len(got.Concurrency) != 0 {
    31			t.Fatalf("explicit empty concurrency was defaulted to %v", got.Concurrency)
    32		}
    33	
    34		// Explicit invalid zeros must reach Validate (and fail there), matching
    35		// the CLI's hard errors, not be silently defaulted.
    36		got = WorkloadSpec{FilesMin: i(0), FilesMax: i(0)}.withDefaults()
    37		if err := got.toWorkload("fmX").Validate(); err == nil {
    38			t.Fatal("explicit files_min=0 should fail Validate like the CLI")
    39		}
    40	}
