    42	// The git-credential helper reply carries sibling keys (password_expiry_utc,
    43	// oauth_refresh_token) that must not be mistaken for the password.
    44	func TestParseGitCredential(t *testing.T) {
    45		out := "capability[]=authtype\nusername=oauth2\npassword=glpat-realsecret\npassword_expiry_utc=1784831031\noauth_refresh_token=deadbeef\n"
    46		user, pass, err := parseGitCredential(out, "glab")
